UPM = DATA["upm"]
D_TOP = DATA["d_top"]             # topo da haste do d: a altura que casa com o b
TRACK = DATA["track"] * UPM       # letter-spacing de -0,01 em
B = DATA["b"]                     # símbolo b. oficial
LOGO = DATA["logo"]               # logo bullet. oficial
VAO_LADO = 0.5 * B["dot_w"]       # meio ponto do b.
VAO_BAIXO = 0.75 * LOGO["dot_w"]  # três quartos do ponto do bullet.
CORES = (("white", "#FFFFFF"), ("black", "#000000"))


def fmt(v):
    s = f"{v:.2f}".rstrip("0").rstrip(".")
    return "0" if s in ("-0", "") else s


def segmentos(d):
    t = d.split()
    i = 0
    while i < len(t):
        c = t[i]
        if c == "Z":
            yield ("Z",)
            i += 1
        elif c in ("M", "L"):
            yield (c, float(t[i + 1]), float(t[i + 2]))
            i += 3
        elif c == "Q":
            yield (c, float(t[i + 1]), float(t[i + 2]), float(t[i + 3]), float(t[i + 4]))
            i += 5
        else:
            raise ValueError(c)


def extremos(a, b, c):
    """Extremos de uma quadrática numa coordenada: pontas e, se houver, o vértice."""
    out = [a, c]
    den = a - 2 * b + c
    if den:
        t = (a - b) / den
        if 0 < t < 1:
            out.append((1 - t) ** 2 * a + 2 * (1 - t) * t * b + t * t * c)
    return out


def desenha(nome, escala, x0, base):
    """O nome em curvas, nas unidades do logo: (path, xmin, xmax)."""
    partes, xs = [], []
    pen = 0.0
    for i, ch in enumerate(nome):
        g = DATA["glyphs"][ch]
        ox = x0 + escala * pen
        atual = None
        for seg in segmentos(g["d"]):
            if seg[0] == "Z":
                partes.append("Z")
                continue
            pts = [(ox + escala * seg[k], base - escala * seg[k + 1]) for k in range(1, len(seg), 2)]
            if seg[0] == "Q":
                (cx, cy), (x, y) = pts
                partes.append(f"Q{fmt(cx)} {fmt(cy)} {fmt(x)} {fmt(y)}")
                xs += extremos(atual[0], cx, x)
            else:
                x, y = pts[0]
                partes.append(f"{seg[0]}{fmt(x)} {fmt(y)}")
                xs.append(x)
            atual = pts[-1]
        pen += g["adv"] + TRACK
        if i + 1 < len(nome):
            pen += DATA["kern"].get(ch + nome[i + 1], 0)
    return "".join(partes), min(xs), max(xs)


def svg(viewbox, fill, paths, d):
    corpo = "".join(f'<path d="{p}"/>' for p in paths)
    return (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="{viewbox}">'
            f'<g fill="{fill}">{corpo}<path d="{d}"/></g></svg>\n')


def lado_a_lado(nome, fill):
    """Padrão: o b. com o nome ao lado, na base dele, a haste do nome na altura do b."""
    s = B["h"] / D_TOP
    d, _, xmax = desenha(nome, s, B["w"] + VAO_LADO, B["h"])
    topo = min(0.0, B["h"] - DATA["asc_max"] * s)
    fundo = B["h"] - DATA["desc_max"] * s
    return svg(f"0 {fmt(topo)} {fmt(xmax)} {fmt(fundo - topo)}", fill, B["paths"], d)


def completo(nome, fill, duas_linhas=False):
    """Variante: o bullet. com o nome embaixo, alinhado pela borda esquerda do b.
    Em duas linhas, uma palavra por linha, cada uma alinhada pela borda esquerda do b;
    entre as linhas, o mesmo vão de três quartos de ponto, da descida de uma à haste da outra."""
    s = LOGO["b_h"] / D_TOP
    base = LOGO["b_h"] + VAO_BAIXO + D_TOP * s
    passo = -DATA["desc_max"] * s + VAO_BAIXO + D_TOP * s
    linhas = nome.split(" ") if duas_linhas else [nome]
    partes, largura = [], LOGO["w"]
    for k, linha in enumerate(linhas):
        b = base + k * passo
        _, xmin, _ = desenha(linha, s, 0.0, b)
        d, _, xmax = desenha(linha, s, -xmin, b)
        partes.append(d)
        largura = max(largura, xmax)
    fundo = base + (len(linhas) - 1) * passo - DATA["desc_max"] * s
    return svg(f"0 0 {fmt(largura)} {fmt(fundo)}", fill, LOGO["paths"], "".join(partes))


def normaliza(nome):
    nome = " ".join(unicodedata.normalize("NFC", nome).lower().split())
    if not nome:
        raise SystemExit("nome vazio")
    fora = sorted({c for c in nome if c not in DATA["glyphs"]})
    if fora:
        raise SystemExit("caracteres fora do conjunto: " + " ".join(fora)
                         + "\naceitos: letras minúsculas, acentos do português e do espanhol, "
                           "números, espaço e hífen")
    return nome


def slug(nome):
    s = "".join(c for c in unicodedata.normalize("NFKD", nome) if not unicodedata.combining(c))
    return "-".join(s.split())


def gera(nome, saida=".", duas_linhas=False):
    nome = normaliza(nome)
    if duas_linhas and len(nome.split(" ")) != 2:
        raise SystemExit("a quebra em duas linhas vale para nome de duas palavras")
    if nome.startswith("bullet "):
        print("aviso: pela regra de nome, Bullet como palavra própria sai do logo "
              "(Bullet Tasks vira tasks)", file=sys.stderr)
    os.makedirs(saida, exist_ok=True)
    feitos = []
    for tom, fill in CORES:
        for sufixo, fn in (("logo", lado_a_lado), ("logo_full", completo)):
            caminho = os.path.join(saida, f"{slug(nome)}_{sufixo}_{tom}.svg")
            with open(caminho, "w", encoding="utf-8") as f:
                f.write(fn(nome, fill))
            feitos.append(caminho)
        if duas_linhas:
            caminho = os.path.join(saida, f"{slug(nome)}_logo_full_2lines_{tom}.svg")
            with open(caminho, "w", encoding="utf-8") as f:
                f.write(completo(nome, fill, True))
            feitos.append(caminho)
    return feitos


def main(argv=None):
    ap = argparse.ArgumentParser(description="Gera o logo com nome da Bullet, pela regra do Identity Source.")
    ap.add_argument("nome", help="o nome como vai no logo, já com a regra de nome aplicada")
    ap.add_argument("--saida", default=".", help="pasta onde gravar os SVG")
    ap.add_argument("--duas-linhas", action="store_true",
                    help="nome de duas palavras: grava também a variante com o nome em duas linhas")
    a = ap.parse_args(argv)
    print("\n".join(gera(a.nome, a.saida, a.duas_linhas)))


if __name__ == "__main__":
    main()
